<?php
namespace Tests\Unit;
use App\Services\Trading\EntryReferenceSelectionPolicyService;
use Tests\TestCase;
class EntryReferenceSelectionPolicyServiceTest extends TestCase
{protected function policy($over=[]){return array_replace_recursive(['schema_version'=>'trading_entry_reference_selection_policy_v1','status'=>'reference_only','policy_id'=>'p','policy_version'=>'v','selection_scope'=>'entry_candidate_reference','selection_mode'=>'single_candidate_reference','candidate_id'=>'c','portfolio_id'=>'pf','portfolio_approval_id'=>'a','requirements'=>['candidate_ready'=>true,'portfolio_reference_approved'=>true],'source'=>['type'=>'synthetic_test_fixture','identifier'=>'x'],'approved_for_reference_selection'=>true,'approved_for_production_selection'=>false,'approved_for_execution'=>false],$over);}protected function ctx($p=null){return ['entry_reference_selection_policy'=>$p??$this->policy(),'action_candidate'=>['schema_version'=>'trading_action_candidate_v1','status'=>'candidate_ready','candidate_id'=>'c'],'portfolio_approval'=>['portfolio_id'=>'pf','status'=>'approved_reference','approval_result'=>['reference_approved'=>true]]];}
 public function test_unavailable_invalid_and_identity_mismatch():void{$svc=new EntryReferenceSelectionPolicyService();$this->assertSame('unavailable',$svc->evaluate([])['status']);$this->assertSame('invalid',$svc->evaluate($this->ctx($this->policy(['schema_version'=>'x'])))['status']);$this->assertSame('blocked',$svc->evaluate($this->ctx($this->policy(['candidate_id'=>'x'])))['status']);}
 public function test_eligible_denied_and_unknown_requirement():void{$svc=new EntryReferenceSelectionPolicyService();$this->assertSame('eligible_for_reference_selection',$svc->evaluate($this->ctx())['status']);$this->assertSame('denied_reference_selection',$svc->evaluate($this->ctx($this->policy(['approved_for_reference_selection'=>false])))['status']);$this->assertSame('invalid',$svc->evaluate($this->ctx($this->policy(['requirements'=>['unknown'=>true]])))['status']);}}
